def compute(vars):
    prior = vars["v1"]
    current = vars["v2"]
    if prior == 0:
        return None
    increase = current - prior
    percent_increase = (increase / prior) * 100
    return {
        "value": percent_increase,
        "trace": {
            "prior_value": prior,
            "current_value": current,
            "increase": increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
